function transCommon(kind){const pw=+S.size.split(',')[0],ph=+S.size.split(',')[1],ts=Math.round(pw*.098);const words=(kind==='in'?'Ahora vamos con cardio':'Ahora vamos con fuerza').split(' ');
 const h1Top=150,leadTop=h1Top+ts*2*.98+16,cardTop=leadTop+(S.fs>1.1?66:48);return{ts,words,h1Top,leadTop,cardTop,ph,pw};}
function wavesSvg(pw,ph,tint){const paths=[];for(let i=0;i<9;i++){const y=ph*.18+i*ph*.085,a=18+i*3;paths.push(`<path d="M-20 ${y} C ${pw*.25} ${y-a}, ${pw*.45} ${y+a}, ${pw*.7} ${y-a*.4} S ${pw+20} ${y+a*.6}, ${pw+40} ${y}" style="opacity:${i>6?.22:.07+i*.01};${i>6?'stroke:'+tint:''};stroke-dasharray:900;stroke-dashoffset:900;animation:wdraw 2.4s ${.1+i*.08}s cubic-bezier(.4,0,.2,1) forwards, wdrift ${9+i}s ${2+i*.2}s ease-in-out infinite alternate"/>`);}
 return `<svg class="waves" viewBox="0 0 ${pw} ${ph}" preserveAspectRatio="none"><style>@keyframes wdraw{to{stroke-dashoffset:0}}@keyframes wdrift{to{transform:translateX(-14px)}}</style>${paths.join('')}</svg>`;}
