 'v-edit':{label:'Editar una captura',group:'Registros',render:()=>tarjetas({micOn:1,set:4,done:3})+voiceExpanded({recs:[RECS[0],{...RECS[2],act:`<div style="margin-top:10px;border-top:1px solid #ffffff0d;padding-top:10px"><div class="eyebrow" style="font-size:9px">REPETICIONES</div><div class="qchips">${[5,6,7,8,9].map(n=>`<button style="${n===8?'background:var(--ink);color:#111':''}">${n}</button>`).join('')}</div><div class="eyebrow" style="font-size:9px;margin-top:10px">ESFUERZO REALIZADO</div><div class="qchips">${['4','3','2','1','0','Fallo'].map(n=>`<button style="${n==='2'?'background:var(--ink);color:#111':''}">${n}</button>`).join('')}</div><div class="vact"><button class="btn secondary">Cancelar</button><button class="btn primary">${ic('check',14)} Confirmar</button></div><div class="diff">Cancelar no cambia la captura original. Confirmar actualiza la serie 3; no crea otra.</div></div>`}]}),
  notes:['Editar abre un borrador dentro del mismo registro. Cancelar no modifica nada.','El esfuerzo realizado se elige siempre; el planificado nunca se copia.']},
