 later(()=>{title.textContent='«Iniciar vídeo»';sub.textContent='Orden reconocida';},900);
 later(()=>{title.textContent='Iniciando grabación…';sub.textContent='Esperando confirmación del grabador';rs.innerHTML='<span class="spin"></span><span>Iniciando</span>';},1600);
 later(()=>{let s=0;title.textContent='Grabando';sub.textContent='Di «Detener vídeo» o pulsa Detener';rs.innerHTML='<span class="recdot"></span><span data-rt>0:00</span>';right(`<button class="btn secondary" style="height:36px;padding:0 12px;font-size:12px">${ic('stop',12)} Detener</button>`);$('[data-recbtn] span',el).style.cssText='width:26px;height:26px;border-radius:6px;background:var(--danger)';every(()=>{s++;const r=$('[data-rt]',el);if(r)r.textContent=clock(s);},1000);},2900);
 later(()=>{grow(el,92);vb.innerHTML='<div class="diff" style="margin-top:0">«Iniciar vídeo» otra vez: ya está grabando. No se crea otro vídeo.</div>';},5200);
 later(()=>{grow(el,56);vb.innerHTML='';title.textContent='«Detener vídeo»';sub.textContent='Deteniendo…';rs.innerHTML='<span class="spin"></span><span>Deteniendo</span>';},7600);
 later(()=>{title.textContent='Guardando vídeo…';sub.textContent='No cierres la captura';rs.innerHTML='<span class="spin"></span><span>Guardando</span>';},8600);
