/* Ajuste del espacio de cardio al dock real: nada queda bajo el dock ni fuera del área. */
function fitCardio(ph){const cd=$('.cdock',ph),body=$('.cardio-body',ph);if(!cd||!body)return;body.style.bottom=(ph.clientHeight-cd.offsetTop+8)+'px';
 const boxes=$$('.page',body);(boxes.length?boxes:[body]).forEach(box=>{const last=box.lastElementChild,rb=$('.ring-box',box);if(!last||!rb)return;const H=box.clientHeight||body.clientHeight;const pad=parseFloat(getComputedStyle(box).paddingTop)||0;
  const over=last.offsetTop+last.offsetHeight-(box===body?H:H);if(over>0){rb.style.setProperty('--ring',Math.max(120,rb.offsetWidth-over-4)+'px');}});}
/* ---------- arnés ---------- */
const TABS={cardio:{label:'Cardio',scenes:CARDIO,first:'c-trans-in',title:'Cardio con espacio propio',intro:'Basado en el rediseño cardio v2 del 16 de octubre, con la identidad del Refinamiento 02: negro, carbón y crema; el color queda solo en las zonas.'},
 voz:{label:'Modo Voz',scenes:VOICE,first:'v-record',title:'Modo Voz como capa viva',intro:'La voz deja de ser una vista aparte. Es una cápsula sobre la sesión que transcribe, convierte la frase en valores y los lleva a su campo.'},
 juegos:{label:'Juegos',scenes:null,first:'g-picker',title:'Minijuegos de descanso, versión propia',intro:'Propuesta nueva: tres juegos más pulidos y jugables, pensados para descansos de 1 a 3 minutos y con el reloj siempre arriba.'}};
function sceneMap(){return S.tab==='juegos'?window.KpknGames.SCENES:TABS[S.tab].scenes;}
function go(id){S.scene=id;render();}
function render(){clearTimers();S.paused=false;const [pw,ph]=S.size.split(',').map(Number),sz=SIZES[S.size],scenes=sceneMap(),sc=scenes[S.scene];
 const root=document.documentElement;root.style.setProperty('--pw',pw+'px');root.style.setProperty('--ph',ph+'px');root.style.setProperty('--pwn',pw);root.style.setProperty('--cw',sz.cw+'px');root.style.setProperty('--ch',sz.ch+'px');root.style.setProperty('--fs',S.fs);root.style.setProperty('--zone',ZC[4]);
 document.body.classList.toggle('reduced',S.reduced);sc.before&&sc.before();
 $('#stage').innerHTML=`<div class="phone-wrap"><div class="phone" data-phone>${sc.render()}<div class="homebar"></div></div></div><aside class="notes"><span class="eyebrow">${TABS[S.tab].label} · ${sc.group}</span><h2>${sc.label}</h2>${sc.notes.map(n=>`<p>${n}</p>`).join('')}<div class="scene-nav"><button data-nav="-1">← Anterior</button>${sc.replay||sc.after?`<button data-replay>Repetir animación ↺</button>`:''}<button data-nav="1">Siguiente escena →</button></div></aside>`;
 const ph_=$('[data-phone]');fitCardio(ph_);sc.after&&sc.after(ph_);
 $('#scene-select').innerHTML='';const groups=[...new Set(Object.values(scenes).map(s=>s.group))];groups.forEach(g=>{const og=document.createElement('optgroup');og.label=g;Object.entries(scenes).filter(([,s])=>s.group===g).forEach(([id,s])=>{const o=document.createElement('option');o.value=id;o.textContent=s.label;o.selected=id===S.scene;og.append(o);});$('#scene-select').append(og);});
 $$('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===S.tab));$('#lab-title').textContent=TABS[S.tab].title;$('#lab-intro').textContent=TABS[S.tab].intro;
 const u=new URL(location);u.searchParams.set('tab',S.tab);u.searchParams.set('scene',S.scene);u.searchParams.set('size',S.size);history.replaceState(null,'',u);}
document.addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t){S.tab=t.dataset.tab;S.scene=TABS[S.tab].first;render();return;}
 const n=e.target.closest('[data-nav]');if(n){const ids=Object.keys(sceneMap()),i=ids.indexOf(S.scene);S.scene=ids[(i+(+n.dataset.nav)+ids.length)%ids.length];render();return;}
 if(e.target.closest('[data-replay]'))render();
 if(e.target.closest('[data-motion]')){S.reduced=!S.reduced;e.target.closest('[data-motion]').setAttribute('aria-pressed',S.reduced);render();}});
$('#scene-select').onchange=e=>go(e.target.value);$('#size-select').onchange=e=>{S.size=e.target.value;render();};$('#font-select').onchange=e=>{S.fs=+e.target.value;render();};
window.KpknProto={S,go,ic,clock,statusbar,island,later,every,timers,say,$,$$};
addEventListener('DOMContentLoaded',()=>{const q=new URLSearchParams(location.search);S.tab=TABS[q.get('tab')]?q.get('tab'):'cardio';S.size=SIZES[q.get('size')]?q.get('size'):'360,740';$('#size-select').value=S.size;S.scene=sceneMap()[q.get('scene')]?q.get('scene'):TABS[S.tab].first;render();});
